-- ─────────────────────────────────────────────────────────────────────────────
-- ME2 DEPRECATED-реестр RPC (R52, план electron-rebuild §D8) — ДЛЯ ОПЕРАТОРА.
-- Источник: живой OpenAPI /rest/v1/ (243 функции). Роль (план §D8): Supabase =
-- federation/evidence/control-plane; SQLite = истина. FREEZE = пометить, НЕ удалять
-- (старые циклы могут ссылаться друг на друга; удаление — отдельное решение оператора).
-- Применение: psql $DATABASE_URL -f 0002-rpc-registry.sql  (после create table).
-- ─────────────────────────────────────────────────────────────────────────────

create table if not exists public.me2_rpc_registry_h205f22 (
  rpc_name   text primary key,
  tier       text not null check (tier in ('ACTIVE','CONTROL_PLANE','FREEZE')),
  decided_at timestamptz not null default now(),
  decided_by text not null default 'R52-registry',
  note       text
);
alter table public.me2_rpc_registry_h205f22 enable row level security;

-- ACTIVE (24): единая система — aop1_* (vercel gateway), supervisor_mesh_*, evidence_*

-- CONTROL_PLANE (37): живые таблицы control-plane (enrollment/lease/command/nonce/pairing)

-- FREEZE (182): старые циклы (duel/macroblock/fabric/fail_run/legacy a2_*) — пометить, не удалять

-- Сводка реестра
select tier, count(*) from public.me2_rpc_registry_h205f22 group by tier order by tier;
